  const a=root; let out:number[]=[];
  function visit(node:TreeNode|null):void{if(!node)return;if(node.val>k)visit(node.left);if(node.val>=k&&node.val<=k+12)out.push(node.val);if(node.val<k+12)visit(node.right);}visit(a);
